<?php require __DIR__.'/includes/bootstrap.php';$title='Audio Library';$tracks=$pdo?$pdo->query("SELECT * FROM audio_tracks WHERE status='published' ORDER BY created_at DESC")->fetchAll():[];require __DIR__.'/includes/header.php';?><div class="container"><h1>Audio Library</h1><p class="muted">Listen to legally owned, licensed, or royalty-free relaxing sounds.</p><div class="grid"><?php foreach($tracks as $t):?><article class="card"><?php if($t['cover_image']):?><img loading="lazy" src="<?=e(media_url($t['cover_image']))?>" alt="<?=e($t['title'])?>" style="max-width:100%;border-radius:12px"><?php endif;?><h2><a href="<?=url('audio/'.$t['slug'].'/')?>"><?=e($t['title'])?></a></h2><p><?=e($t['description']??'')?></p><?php if($t['audio_url']):?><audio controls preload="none" src="<?=e(media_url($t['audio_url']))?>"></audio><?php endif;?><p class="muted"><?=e($t['category']??'')?> &middot; <?=e((string)$t['plays'])?> plays</p></article><?php endforeach;?></div><?php if(!$tracks):?><p>No published audio is available yet.</p><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
